//! Cargo-driven `jscript.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is jscript-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x735b0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff03000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff03000000u64)),
        o => panic!("jscript-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/jscript/jsglobal_t.o", "dll/win32/jscript/jscript_classes_r.o", "body", "engine:uuid", "engine:wine", "engine:oldnames", "engine:c:wine_dll_register", "import:user32", "import:ole32", "import:oleaut32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll"],
        "x86_64" => &["dll/win32/jscript/jsglobal_t.o", "dll/win32/jscript/jscript_classes_r.o", "body", "engine:uuid", "engine:wine", "engine:oldnames", "engine:c:wine_dll_register", "import:user32", "import:ole32", "import:oleaut32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll"],
        "aarch64" => &["dll/win32/jscript/jsglobal_t.o", "dll/win32/jscript/jscript_classes_r.o", "body", "engine:uuid", "engine:wine", "engine:oldnames", "engine:c:wine_dll_register", "import:user32", "import:ole32", "import:oleaut32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/jscript",
        "dll/win32/jscript",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "vendor/zlib/include",
        "sdk/lib/tdilib",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .rust_staticlib("jscript-rust")
        .c_from_compile_db("jscript_shims", &["dll/win32/jscript/activex.c", "dll/win32/jscript/array.c", "dll/win32/jscript/arraybuf.c", "dll/win32/jscript/bool.c", "dll/win32/jscript/compile.c", "dll/win32/jscript/date.c", "dll/win32/jscript/dispex.c", "dll/win32/jscript/engine.c", "dll/win32/jscript/enumerator.c", "dll/win32/jscript/error.c", "dll/win32/jscript/function.c", "dll/win32/jscript/global.c", "dll/win32/jscript/jscript.c", "dll/win32/jscript/jscript_main.c", "dll/win32/jscript/json.c", "dll/win32/jscript/jsregexp.c", "dll/win32/jscript/jsstr.c", "dll/win32/jscript/jsutils.c", "dll/win32/jscript/lex.c", "dll/win32/jscript/math.c", "dll/win32/jscript/number.c", "dll/win32/jscript/object.c", "dll/win32/jscript/regexp.c", "dll/win32/jscript/set.c", "dll/win32/jscript/string.c", "dll/win32/jscript/vbarray.c", "dll/win32/jscript/guid.c", "dll/win32/jscript/cc_parser.tab.c", "dll/win32/jscript/parser.tab.c"])
        .rc("dll/win32/jscript/rsrc.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/jscript/jscript.spec", "jscript.dll")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
